class PublicBookingScreen extends StatefulWidget{const PublicBookingScreen({super.key,required this.viewModel});final PublicBookingViewModel viewModel;@override State<PublicBookingScreen>createState()=>_PublicBookingScreenState();}
class _PublicBookingScreenState extends State<PublicBookingScreen>{final login=TextEditingController();@override void initState(){super.initState();widget.viewModel.addListener(refresh);}@override void dispose(){widget.viewModel.removeListener(refresh);login.dispose();super.dispose();}void refresh(){if(mounted)setState((){});}@override Widget build(BuildContext c){final data=widget.viewModel.data;return ZenPage(title:'Agendamento público',children:[ZenCard(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('Catálogo da barbearia',style:TextStyle(fontWeight:FontWeight.w900,fontSize:18)),const SizedBox(height:6),const Text('Consulte profissionais e disponibilidade pelo link público.',style:TextStyle(color:ZenColors.muted)),const SizedBox(height:16),TextField(controller:login,decoration:const InputDecoration(labelText:'Login público da barbearia')),const SizedBox(height:12),FilledButton(onPressed:()=>widget.viewModel.load(login.text.trim()),child:const Text('Abrir catálogo público'))])),if(widget.viewModel.error!=null)Padding(padding:const EdgeInsets.only(top:12),child:ZenCard(child:Text(widget.viewModel.error!))),if(data!=null)...[const SizedBox(height:16),ZenCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${data['owner']['shop_name']}',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:10),for(final barber in(data['barbers']as List))Padding(padding:const EdgeInsets.only(bottom:8),child:ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(child:Icon(Icons.content_cut)),title:Text('${barber['name']}',style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text('${barber['work_start']}–${barber['work_end']}',style:const TextStyle(color:ZenColors.muted)),trailing:const ZenStatusPill(label:'Disponível',color:ZenColors.green)))]))]]);}}
